const hosts=[{id:1,name:'Sofia Rose',age:24,country:'🇨🇴 Colombia',viewers:'2.4k',bio:'A little music, a little magic ✨',tags:['Just chatting','Music'],img:'photo-1534528741775-53994a69daeb',level:28},{id:2,name:'Mia Chen',age:25,country:'🇰🇷 South Korea',viewers:'1.8k',bio:'Your favorite late-night conversation 🌙',tags:['Just chatting','Chill'],img:'photo-1524504388940-b1c1722653e1',level:32},{id:3,name:'Isabella',age:26,country:'🇧🇷 Brazil',viewers:'3.1k',bio:'Good vibes & a little dancing 💃',tags:['Dance','Music'],img:'photo-1524250502761-1ac6f2e30d43',level:41},{id:4,name:'Luna Sky',age:23,country:'🇺🇸 United States',viewers:'986',bio:'Come hang out in my little universe 🪐',tags:['Gaming','Chill'],img:'photo-1517841905240-472988babdf9',level:19},{id:5,name:'Emma Wilson',age:27,country:'🇬🇧 United Kingdom',viewers:'1.2k',bio:'Coffee, conversations & you ☕',tags:['Just chatting','Chill'],img:'photo-1531123897727-8f129e1688ce',level:24},{id:6,name:'Valentina',age:25,country:'🇪🇸 Spain',viewers:'2.7k',bio:'Let’s make tonight unforgettable ✨',tags:['Dance','Just chatting'],img:'photo-1529139513065-cff0f4c39491',level:35},{id:7,name:'Aria Bloom',age:24,country:'🇨🇦 Canada',viewers:'842',bio:'Acoustic evenings & soulful moments 🎸',tags:['Music','Chill'],img:'photo-1488426862026-3ee34a7d66df',level:22},{id:8,name:'Jade',age:26,country:'🇫🇷 France',viewers:'1.6k',bio:'A little fun. A lot of personality 🦋',tags:['Gaming','Just chatting'],img:'photo-1534751516642-a1af1ef26a56',level:29}];
const gifts=[['🌹','Rose',10],['💜','Love',50],['💎','Diamond',100],['🧸','Teddy bear',250],['👑','Crown',500],['🚀','Rocket',1000]];let state=loadState()||{coins:1250,following:[],name:'Alex Morgan',bio:'Here for good conversations and great vibes.',spent:0};let category='All live',query='',currentHost=null;const app=document.querySelector('#app');const pic=(h,w=650)=>`https://images.unsplash.com/${h.img}?auto=format&fit=crop&w=${w}&q=85`;function loadState(){try{const value=JSON.parse(localStorage.getItem('flirtlive')||'null');if(!value||typeof value.name!=='string'||typeof value.bio!=='string'||!Array.isArray(value.following)||!Number.isSafeInteger(value.coins)||value.coins<0||!Number.isSafeInteger(value.spent)||value.spent<0)return null;return value}catch{return null}}function persist(){try{localStorage.setItem('flirtlive',JSON.stringify(state))}catch{toast('Browser storage is full or unavailable. Changes may not survive reload.')}document.querySelector('#balance').textContent=state.coins.toLocaleString();const roomBalance=document.querySelector('#room-balance');if(roomBalance)roomBalance.textContent=state.coins.toLocaleString()}function toast(t){let e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),3200)}function modal(html){const d=document.querySelector('#modal');d.innerHTML=html+'<button style="margin-top:15px" onclick="document.querySelector(\'#modal\').close()">Close</button>';d.showModal()}function follow(id,event){event?.stopPropagation();state.following.includes(id)?state.following=state.following.filter(x=>x!==id):state.following.push(id);persist();if(currentHost&&location.hash.startsWith('#room/')){const button=document.querySelector('.stage-bottom .primary');button.textContent=state.following.includes(id)?'♥ Following':'♡ Follow host'}else render();toast(state.following.includes(id)?'Added to your following':'Removed from following')}function card(h){return `<article class="card" onclick="location.hash='room/${h.id}'" tabindex="0" onkeydown="if(event.key==='Enter')location.hash='room/${h.id}'"><div class="photo"><img src="${pic(h)}" alt="${h.name}" loading="lazy"><span class="live-tag">LIVE</span><span class="viewers">◉ ${h.viewers}</span><span class="country">${h.country}</span><button class="heart" aria-label="Follow ${h.name}" onclick="follow(${h.id},event)">${state.following.includes(h.id)?'♥':'♡'}</button></div><div class="card-info"><div class="name-row"><strong>${h.name} <span class="verified">✦</span></strong><span class="level">LV. ${h.level}</span></div><p>${h.bio}</p><div class="tags">${h.tags.map(t=>`<span>${t}</span>`).join('')}</div></div></article>`}function filters(){return `<div class="categories">${['All live','Just chatting','Music','Dance','Gaming','Chill'].map((t,i)=>`<button class="${category===t?'active':''}" onclick="category='${t}';render()">${['✦','☏','♫','♧','⌘','☾'][i]} &nbsp; ${t}</button>`).join('')}<button class="filter" onclick="showFilters()">☷ &nbsp; Filters</button></div>`}function filtered(following=false){return hosts.filter(h=>(!following||state.following.includes(h.id))&&(category==='All live'||h.tags.includes(category))&&`${h.name} ${h.country} ${h.tags}`.toLowerCase().includes(query.toLowerCase()))}function hero(){return `<section class="hero"><img class="hero-img" src="${pic(hosts[0],1400)}" alt="Featured host Sofia Rose"><div class="hero-content"><div class="eyebrow">A WORLD OF LIVE CONNECTIONS</div><h1>Find your people.<br>Feel the <em>connection.</em></h1><p>Meet incredible people. Share real moments.<br>Your next favorite connection is live right now.</p><button class="primary" onclick="document.querySelector('#live').scrollIntoView({behavior:'smooth'})">Explore live &nbsp; ↗</button><button class="secondary" onclick="goLive()">▷ &nbsp; Go live</button></div><a class="hero-float" href="#room/1"><span class="live-tag">LIVE</span><div><strong>Sofia Rose ✦</strong><p>Good energy looks good on you ✨</p></div><span>↗</span></a></section>`}function home(mode){const list=filtered(mode==='following');app.innerHTML=`${mode==='home'?hero():`<div class="eyebrow">FIND YOUR CONNECTION</div><h1 class="page-title">${mode==='following'?'Your favorites, live.':'Discover your vibe.'}</h1><p class="sub">${mode==='following'?'The people you love spending time with.':'A world of personalities. One connection away.'}</p>`}<div class="intro" id="live"><div><h2>${mode==='home'?'<span>●</span> Live right now':mode==='following'?'Following':'Meet someone new'}</h2><p>${mode==='home'?'Real people. Good energy. Endless possibilities.':'Explore live hosts and find your next favorite.'}</p></div><div class="online">1,248 hosts online <span style="margin-left:18px;color:#b78fea">Recommended ⌄</span></div></div>${filters()}<div class="grid">${list.map(card).join('')||'<div class="empty">No hosts found. Try another category or follow a host.</div>'}</div><div class="load"><button onclick="toast('You’ve seen all live hosts in this demo. Check another category!')">You’re all caught up &nbsp; ✓</button></div><section class="community"><div><h3>A little hello can start something great. ✨</h3><p>Find your community, share your story, and make every moment count.</p></div><button class="primary" onclick="goLive()">Start your journey ↗</button></section>`}function room(id){const h=hosts.find(x=>x.id===+id)||hosts[0];currentHost=h;app.innerHTML=`<p class="sub"><a href="#home">← Back to explore</a> &nbsp; / &nbsp; ${h.name}’s room</p><div class="room"><section class="stage"><img src="${pic(h,1200)}" alt="${h.name}"><div class="stage-overlay"><div class="stage-head"><span class="live-tag">LIVE ROOM DEMO</span><span>◉ ${h.viewers} viewers</span></div><div class="stage-bottom"><span class="country">${h.country} · ${h.age}</span><h2>${h.name} <span class="verified">✦</span></h2><p>${h.bio}</p><button class="primary" onclick="follow(${h.id},event)">${state.following.includes(h.id)?'♥ Following':'♡ Follow host'}</button><button onclick="shareRoom()">↗ Share</button></div></div></section><section class="panel chat-panel"><strong>Live chat <span style="color:#8d819c;font-size:10px;float:right">ROOM DEMO</span></strong><div class="chat-log" id="chat"><p><b>FlirtLive</b> Welcome to ${h.name}’s room. Be kind and enjoy the moment 💜</p><p><b>Jamie</b> The energy in here ✨</p><p><b>Oliver</b> Hey everyone! 👋</p><p><b>${h.name}</b> So happy you’re here 💜</p></div><form class="chat-form" onsubmit="sendChat(event)"><input class="field" id="chat-input" maxlength="300" placeholder="Say something nice…" aria-label="Chat message" required><button class="primary" aria-label="Send message">➤</button></form></section></div><section class="panel room-gifts"><div class="name-row"><strong>Make their moment ✨</strong><span class="sub">Your balance: 🪙 <span id="room-balance">${state.coins.toLocaleString()}</span></span></div><div class="gift-grid">${gifts.map((g,i)=>`<button class="gift" onclick="sendGift(${i})"><span>${g[0]}</span>${g[1]}<small>🪙 ${g[2]}</small></button>`).join('')}</div><p class="sub" style="font-size:11px">Demo room · Portrait preview · Chat and gifts are saved on this device. No live broadcast is connected.</p></section>`;if(Array.isArray(state.chats?.[h.id])){const log=document.querySelector('#chat');log.replaceChildren();state.chats[h.id].forEach(text=>{const line=document.createElement('p');line.textContent=String(text);log.append(line)})}}function shareRoom(){if(!navigator.clipboard)return toast('Copy the room URL from your address bar');navigator.clipboard.writeText(location.href).then(()=>toast('Room link copied')).catch(()=>toast('Could not copy. Copy the URL from your address bar'))}function saveChat(){if(!currentHost)return;state.chats=state.chats||{};state.chats[currentHost.id]=Array.from(document.querySelector('#chat').children).map(p=>p.textContent).slice(-100);persist()}function sendChat(e){e.preventDefault();let input=document.querySelector('#chat-input');if(!input.value.trim())return;let p=document.createElement('p'),b=document.createElement('b');b.textContent=state.name+' ';p.append(b,document.createTextNode(input.value));document.querySelector('#chat').append(p);input.value='';saveChat();p.scrollIntoView({block:'nearest'})}function sendGift(i){const g=gifts[i];if(state.coins<g[2])return toast('You need more coins. Visit My coins to top up.');state.coins-=g[2];state.spent+=g[2];persist();let p=document.createElement('p');p.textContent=`${state.name} sent ${g[0]} ${g[1]} to ${currentHost.name}!`;document.querySelector('#chat').append(p);saveChat();toast(`${g[0]} ${g[1]} sent!`)}function coins(){app.innerHTML=`<div class="eyebrow">A LITTLE GIFT. A BIG SMILE.</div><h1 class="page-title">Spread a little love.</h1><p class="sub">Support your favorite creators with gifts that make their day.</p><div class="panel name-row" style="margin-top:25px"><span>Your coin balance</span><h2>🪙 ${state.coins.toLocaleString()} <small style="font-size:12px;color:#a08fac">coins</small></h2></div><div class="packages">${[[500,'$4.99','A little hello'],[1200,'$9.99','Most popular · 20% bonus'],[3000,'$24.99','Keep the good vibes going']].map((p,i)=>`<div class="panel package"><div class="coin-icon">${['🪙','💰','💎'][i]}</div><h2>${p[0].toLocaleString()} <small style="font-size:13px">coins</small></h2><p class="sub">${p[2]}</p><button class="${i===1?'primary':''}" onclick="buyCoins(${p[0]})">Add demo coins · ${p[1]}</button></div>`).join('')}</div><p class="sub">Demo wallet: packages add test coins. No payment is collected.</p><h2>Find the perfect gift</h2><div class="gift-grid">${gifts.map(g=>`<div class="gift"><span>${g[0]}</span>${g[1]}<small>🪙 ${g[2]} coins</small></div>`).join('')}</div>`}function buyCoins(n){state.coins+=n;persist();coins();toast(`${n.toLocaleString()} demo coins added to your wallet`)}function leaderboard(){let ranked=[hosts[2],hosts[0],hosts[5],hosts[1],hosts[7],hosts[4],hosts[6],hosts[3]];app.innerHTML=`<div class="eyebrow">THE SPOTLIGHT IS THEIRS</div><h1 class="page-title">Top Live <span style="color:#b88bf1">♕</span></h1><p class="sub">Meet the creators making the biggest waves this week. · Demo rankings</p><div class="podium">${[ranked[1],ranked[0],ranked[2]].map((h,i)=>`<a href="#room/${h.id}" class="panel"><div style="font-size:26px;margin-bottom:18px">${['🥈','👑','🥉'][i]}</div><img src="${pic(h,250)}" alt="${h.name}"><h2>${h.name} ✦</h2><p class="sub">${h.country}</p><strong style="color:#c99aff">${['182,450','248,920','156,800'][i]} 🪙</strong></a>`).join('')}</div><div class="panel">${ranked.map((h,i)=>`<a class="rank-row" href="#room/${h.id}"><span style="color:#b791e4;width:20px">${i+1}</span><img src="${pic(h,100)}" alt=""><strong>${h.name} <small class="verified">✦</small></strong><span class="sub">${h.viewers} viewers</span><span>↗</span></a>`).join('')}</div>`}function profile(){app.innerHTML=`<div class="eyebrow">YOUR LITTLE CORNER</div><h1 class="page-title">My profile</h1><p class="sub">Let a little of your personality shine.</p><div class="profile-layout"><section class="panel profile-summary"><div class="avatar me profile-avatar">${escapeHtml(state.name.charAt(0))}</div><h2>${escapeHtml(state.name)}</h2><span class="level">✧ LEVEL 12 · EXPLORER</span><div class="stats"><div><b>${state.following.length}</b><small>Following</small></div><div><b>${state.spent}</b><small>Coins gifted</small></div></div><div class="progress"><div></div></div><small class="sub">450 / 1,000 XP to level 13</small></section><section class="panel"><h2>Edit profile</h2><form class="profile-form" onsubmit="saveProfile(event)"><label>Display name<input class="edit" name="name" value="${escapeHtml(state.name)}" maxlength="40" required></label><label>About you<textarea name="bio" rows="4" maxlength="240">${escapeHtml(state.bio)}</textarea></label><label>Profile photo<input type="file" accept="image/*" onchange="uploadAvatar(event)"></label><button class="primary">Save changes</button></form></section></div>`;if(typeof state.avatar==='string'&&/^data:image\/(png|jpeg|webp|gif);base64,/.test(state.avatar))document.querySelector('.profile-avatar').innerHTML=`<img src="${state.avatar}" style="width:100%;height:100%;object-fit:cover;border-radius:50%" alt="Your profile">`}function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function saveProfile(e){e.preventDefault();const name=e.target.elements.namedItem('name').value.trim();if(!name)return toast('Please enter a display name');state.name=name;state.bio=e.target.elements.namedItem('bio').value.trim();persist();profile();toast('Profile updated')}function uploadAvatar(e){let file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))return toast('Choose a PNG, JPEG, WebP, or GIF image');if(file.size>2000000)return toast('Please choose an image under 2 MB');let reader=new FileReader;reader.onload=()=>{state.avatar=reader.result;persist();profile();toast('Profile photo updated')};reader.readAsDataURL(file)}function messages(){app.innerHTML=`<div class="eyebrow">KEEP THE CONVERSATION GOING</div><h1 class="page-title">Messages</h1><p class="sub">Your connections start with a hello.</p><div class="panel">${hosts.slice(0,3).map((h,i)=>`<a class="rank-row" href="#room/${h.id}"><img src="${pic(h,100)}" alt=""><strong>${h.name}<p class="sub" style="font-size:12px;font-weight:400">${['Welcome! Come say hello in my room 💜','I’m live — join the conversation!','Sending good vibes your way ✨'][i]}</p></strong><span class="level">Join room ↗</span></a>`).join('')}<p class="sub" style="font-size:11px">Sample invitations. Private messaging requires a connected messaging service.</p></div>`}function goLive(){modal('<div class="eyebrow">TAKE THE STAGE</div><h2>Your story deserves an audience.</h2><p>This preview shows the host experience. Live broadcasting requires a streaming provider, host verification, and camera permissions.</p><p>Host application interest is saved locally.</p><button class="primary" onclick="localStorage.setItem(\'hostInterest\',\'true\');document.querySelector(\'#modal\').close();toast(\'Host interest saved on this device\')">I’m interested in hosting</button>')}function showFilters(){modal(`<h2>Find your people</h2><p>Filter by country</p><select class="field" id="country-filter"><option value="">Everywhere</option>${hosts.map(h=>`<option value="${h.country.split(' ').slice(1).join(' ')}">${h.country}</option>`).join('')}</select><p><button class="primary" onclick="query=document.querySelector('#country-filter').value;document.querySelector('#search').value=query;document.querySelector('#modal').close();render()">Apply filter</button> <button onclick="query='';category='All live';document.querySelector('#search').value='';document.querySelector('#modal').close();render()">Reset</button></p>`)}function render(){let [page,id]=(location.hash.slice(1)||'home').split('/');document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));document.querySelector('#crumb').textContent=({home:'Home',discover:'Discover',top:'Top Live',following:'Following',coins:'My coins',profile:'My profile',room:'Live room',messages:'Messages'})[page]||'Home';if(['home','discover','following'].includes(page))home(page);else if(page==='room')room(id);else if(page==='coins')coins();else if(page==='top')leaderboard();else if(page==='profile')profile();else if(page==='messages')messages();else home('home');persist()}window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});document.querySelector('#search').addEventListener('input',e=>{query=e.target.value;if(!['home','discover','following'].includes(location.hash.slice(1)))location.hash='discover';else render()});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();document.querySelector('#search').focus()}});render();
